from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from rest_framework_simplejwt.token_blacklist.models import OutstandingToken, BlacklistedToken

class RevokeSessionTokenView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, token_id):
        try:
            token = OutstandingToken.objects.get(id=token_id)
        except OutstandingToken.DoesNotExist:
            return Response({"detail": "Token not found"}, status=status.HTTP_404_NOT_FOUND)

        if token.user_id != request.user.id and not request.user.is_staff:
            return Response({"detail": "Access denied to specified token session"}, status=status.HTTP_403_FORBIDDEN)

        BlacklistedToken.objects.get_or_create(token=token)
        return Response({"status": "token_blacklisted", "token_id": token_id})
